# xdom-50 考卷 · Kaggle Benchmarks 移植版 · CALIB PILOT (组1-30, 判分法=园内判卷律)
import kaggle_benchmarks as kbench
import base64, json
_D = json.loads(base64.b64decode(""))
_NL = "、".join(_D["names"])

@kbench.task(name="XDOM Calib Pilot", description="跨域路由考卷 calib(1-30): 上下文判入 172 概念空间, 闭集, 严格名匹配")
def xdom_calib(llm) -> None:
    tot = 0; hit = 0
    for g in _D["probes"]:
        for pr in g["probes"]:
            tot += 1
            ans = llm.prompt(
                "以下是概念空间名列表(闭集):\n" + _NL +
                "\n\n请判断这段语境最应归入哪个概念空间, 只输出该空间名本身, 不要解释:\n语境: " + pr["context"],
                temperature=0).strip()
            good = (ans == pr["expected"]) or (pr["expected"] in ans and len(ans) <= len(pr["expected"]) + 6)
            hit += 1 if good else 0
            kbench.assertions.assert_true(good, expectation=f"no{g['no']}→{pr['expected']} (答:{ans[:24]})")
    print(f"XDOM-CALIB acc = {hit}/{tot} = {hit/max(1,tot):.3f}")

xdom_calib.run(kbench.llm)
